here = fileparts(mfilename('fullpath'));  root = fileparts(fileparts(here));  addpath(here);  addpath(genpath(fullfile(root, 'model')));
fo = fullfile(root, 'test_results', 'temp_3d_wsonly');  load(fullfile(fo, 'temp_1103_flow.mat'), 'r');  cfg = canonical_scenario(0.05, 1.10, 'ramp_tri', 1);  params = calc_simulation_params(cfg);  P = params.Value;  a_o = P.common.Ts / P.common.gamma_N / P.common.R;  FS = 14;  cE = [0 0.25 0.85];
n = find(isfinite(r.aN(1:r.kend)), 1, 'last');  n = min(n, size(r.fa, 1));  t = r.t(1:n);  t = t(:);  F = zeros(n, 3);  D = NaN(n, 3);  f = r.fa(1:n, :) / a_o;
for i = 1:n; c = r.thx(i) * pi / 180;  s = r.thy(i) * pi / 180;  V = [cos(s) 0 sin(s); 0 1 0; -sin(s) 0 cos(s)] * [1 0 0; 0 cos(c) -sin(c); 0 sin(c) cos(c)];  F(i, :) = (V' * f(i, :)')';  if i > 1 && i < n; c0 = r.thx(i - 1) * pi / 180;  s0 = r.thy(i - 1) * pi / 180;  V0 = [cos(s0) 0 sin(s0); 0 1 0; -sin(s0) 0 cos(s0)] * [1 0 0; 0 cos(c0) -sin(c0); 0 sin(c0) cos(c0)];  D(i, :) = (V0' * (r.pd(i + 1, :) - r.pd(i, :))')'; end; end
W = {t < 10, t >= 10 & t < r.tsc, t >= r.tsc + 0.5 & t <= r.rs_tend};  wn = {'hold', 'descent', 'scan'};
for j = 1:3; m = W{j}; fprintf('%-8s rms F_u %.2f F_v %.2f F_w %.2f pN | max |F| u %.1f v %.1f w %.1f pN\n', wn{j}, rms(F(m, 1)), rms(F(m, 2)), rms(F(m, 3)), max(abs(F(m, 1))), max(abs(F(m, 2))), max(abs(F(m, 3)))); end
k = (1:3:n)';  L = {'F_u', 'F_v', 'F_w'};  LD = {'\Delta u_d', '\Delta v_d', '\Delta w_d'};  m = t >= r.tsc + 0.5 & t <= r.rs_tend;  lin = m & abs(D(:, 2)) < 1e-3;  fprintf('scan line steps: |du| median %.5f um, sd %.2e um, min %.5f, max %.5f | v steps %.4f um | w step rms %.2f nm\n', median(abs(D(lin, 1))), std(abs(D(lin, 1))), min(abs(D(lin, 1))), max(abs(D(lin, 1))), median(abs(D(m & ~lin, 2))), 1e3 * rms(D(m, 3)));
g = figure('Color', 'w', 'Position', [40 40 1900 1000], 'Visible', 'off');  tl = tiledlayout(3, 2, 'TileSpacing', 'compact', 'Padding', 'compact', 'TileIndexing', 'rowmajor');
for q = 1:3
    a = nexttile(tl);  plot(a, t(k), F(k, q), 'Color', cE, 'LineWidth', 0.5);  ylim(a, [-25 25]);  xlim(a, [0 t(end)]);  ylabel(a, [L{q} '  [pN]']);  if q == 3; xlabel(a, 'Time (sec)'); end
    b = nexttile(tl);  plot(b, t(k), D(k, q), 'Color', cE, 'LineWidth', 0.6);  xlim(b, [0 t(end)]);  ylabel(b, [LD{q} '  [\mum per step]']);  if q == 3; xlabel(b, 'Time (sec)'); end
    for c = [a b]; box(c, 'on');  set(c, 'FontSize', FS, 'FontWeight', 'bold', 'LineWidth', 1.2); end
end
fn = fullfile(fo, 'fig_1103_flow_force_local.png');  exportgraphics(g, fn, 'Resolution', 130);  close(g);  system(['open -a Preview "' fn '"']);
